// Every rule an accounts payable clerk applies by hand, in one place.
// Nothing here talks to an API. It compares what the model read off the PDF
// against the supplier master, the open purchase orders and what is already
// in the ledger, then says post it, hold it, or reject it, and why.

const inv = $('Pull the invoice fields').first().json.output || $('Pull the invoice fields').first().json;

const suppliers = $('Supplier master').all().map(i => i.json);
const orders    = $('Open purchase orders').all().map(i => i.json);
const posted    = $('Invoices already posted').all().map(i => i.json);

// ---- tolerances you may want to change -------------------------------------
const ROUNDING_TOLERANCE = 0.02;   // currency units allowed on subtotal + tax = total
const PO_TOLERANCE_PCT   = 2;      // percent an invoice may exceed the PO line
const MAX_AGE_DAYS       = 120;    // older than this is almost always a duplicate claim
const APPROVAL_LIMIT     = 10000;  // above this a human signs it off even when clean
const VALID_TAX_RATES    = [0, 5]; // UAE standard and zero rated
// ----------------------------------------------------------------------------

const norm = s => String(s == null ? '' : s).toLowerCase().replace(/\b(llc|l\.l\.c|fzco|fze|fzc|ltd|limited|inc|co|company|est|establishment|trading llc)\b/g, '').replace(/[^a-z0-9]/g, '').trim();
const num  = v => { const s = String(v == null ? '' : v).replace(/[^0-9.\-]/g, ''); if (s === '' || s === '-' || s === '.') return null; const n = Number(s); return Number.isFinite(n) ? n : null; };
const days = d => { const t = Date.parse(d); return Number.isFinite(t) ? Math.round((Date.now() - t) / 86400000) : null; };

const failures = [];
const warnings = [];

// 1. Did the model actually read the document
const required = ['supplier', 'invoice_number', 'issue_date', 'total'];
const missing = required.filter(f => inv[f] === null || inv[f] === undefined || inv[f] === '');
if (missing.length) failures.push('Could not read ' + missing.join(', ') + ' from the document');

// 2. Is this supplier one we buy from
const supplier = suppliers.find(s => norm(s.supplier_name) === norm(inv.supplier));
if (!supplier) failures.push('Supplier "' + inv.supplier + '" is not on the supplier master');

// 3. Have we already paid this one
const dupe = posted.find(p => norm(p.supplier) === norm(inv.supplier) && String(p.invoice_number).trim() === String(inv.invoice_number).trim());
if (dupe) failures.push('Invoice ' + inv.invoice_number + ' from this supplier is already posted on row ' + (dupe.row_number || 'unknown'));

// 4. Does the invoice add up
const sub = num(inv.subtotal), tax = num(inv.tax_amount), tot = num(inv.total);
if (sub !== null && tax !== null && tot !== null) {
  const diff = Math.abs((sub + tax) - tot);
  if (diff > ROUNDING_TOLERANCE) failures.push('Subtotal ' + sub + ' plus tax ' + tax + ' is ' + (sub + tax).toFixed(2) + ', but the invoice total says ' + tot);
}

// 5. Is the tax rate one that exists here
if (sub !== null && tax !== null && sub > 0) {
  const rate = Math.round((tax / sub) * 1000) / 10;
  if (!VALID_TAX_RATES.some(r => Math.abs(rate - r) < 0.3)) failures.push('Tax works out at ' + rate + ' percent, which is not a rate in use');
}

// 6. A tax number when tax is charged
if (tax !== null && tax > 0) {
  const trn = String(inv.supplier_tax_number || '').replace(/\D/g, '');
  if (!trn) failures.push('Tax is charged but the invoice shows no supplier tax registration number');
  else if (trn.length !== 15) failures.push('Supplier tax registration number is ' + trn.length + ' digits, it should be 15');
}

// 7. Does it match an open purchase order
let po = null;
if (inv.po_number) {
  po = orders.find(o => String(o.po_number).trim().toLowerCase() === String(inv.po_number).trim().toLowerCase());
  if (!po) failures.push('Purchase order ' + inv.po_number + ' is not open');
  else {
    const remaining = num(po.remaining_value);
    if (remaining !== null && tot !== null && tot > remaining * (1 + PO_TOLERANCE_PCT / 100)) {
      failures.push('Invoice of ' + tot + ' exceeds the ' + remaining + ' left on purchase order ' + po.po_number);
    }
    if (po.currency && inv.currency && String(po.currency).toUpperCase() !== String(inv.currency).toUpperCase()) {
      failures.push('Invoice is in ' + inv.currency + ' but purchase order ' + po.po_number + ' is in ' + po.currency);
    }
  }
} else if (supplier && String(supplier.po_required).toLowerCase() === 'yes') {
  failures.push('This supplier requires a purchase order and none is quoted on the invoice');
}

// 8. Is the date sane
const age = days(inv.issue_date);
if (age === null) failures.push('Issue date "' + inv.issue_date + '" is not a date we can read');
else if (age < -1) failures.push('Issue date is in the future');
else if (age > MAX_AGE_DAYS) warnings.push('Invoice is ' + age + ' days old');

// ---- the decision ----------------------------------------------------------
let decision, reason;
if (failures.length) {
  decision = 'reject';
  reason = failures.join('. ');
} else if (tot !== null && tot > APPROVAL_LIMIT) {
  decision = 'approve';
  reason = 'Every check passed but ' + tot + ' ' + (inv.currency || '') + ' is above the ' + APPROVAL_LIMIT + ' limit, so it needs a signature';
} else {
  decision = 'post';
  reason = 'Every check passed and the amount is inside the limit';
}

return [{
  json: {
    decision: decision,
    reason: reason,
    failed_checks: failures.length,
    failures: failures,
    warnings: warnings,
    supplier: inv.supplier,
    supplier_email: supplier ? supplier.supplier_email : null,
    approver_email: po ? po.approver_email : (supplier ? supplier.default_approver : null),
    invoice_number: inv.invoice_number,
    po_number: inv.po_number || null,
    issue_date: inv.issue_date,
    due_date: inv.due_date || null,
    currency: inv.currency || null,
    subtotal: sub,
    tax_amount: tax,
    total: tot,
    checked_at: new Date().toISOString()
  }
}];

